import os,secrets,hmac,hashlib,time
from pathlib import Path
from fastapi import FastAPI,Request,HTTPException
from fastapi.responses import HTMLResponse,JSONResponse
from pydantic import BaseModel
from . import operator
from .ops import list_tasks,render_services
VERSION='3.0.0-beta.2';DATA=Path(os.getenv('JARVIS3_DATA_DIR','/app/data'));DATA.mkdir(parents=True,exist_ok=True);SECRET_FILE=DATA/'jarvis3_session_secret'
if SECRET_FILE.exists():SECRET=SECRET_FILE.read_text().strip().encode()
else:SECRET=secrets.token_hex(48).encode();SECRET_FILE.write_text(SECRET.decode())
COOKIE='jarvis3_owner';app=FastAPI(title='Panther Peptides - Jarvis 3',version=VERSION)
def sign(b):return hmac.new(SECRET,b.encode(),hashlib.sha256).hexdigest()
def session():b=f'owner:{int(time.time())}';return b+'.'+sign(b)
def valid(t):
 try:b,s=t.rsplit('.',1);role,ts=b.split(':',1);return role=='owner' and hmac.compare_digest(s,sign(b)) and 0<=int(time.time())-int(ts)<2592000
 except:return False
def owner(r):
 if not valid(r.cookies.get(COOKIE,'')):raise HTTPException(401,'Owner authentication required')
class Login(BaseModel):password:str
class Objective(BaseModel):objective:str;priority:int=50
class Decision(BaseModel):approved:bool
@app.on_event('startup')
def startup():operator.start()
@app.get('/health')
def health():return {'ok':True,'service':'jarvis3-operator','version':VERSION,'operator':operator.status()}
@app.get('/ready')
def ready():return {'ok':bool(os.getenv('JARVIS_OWNER_PASSWORD') and os.getenv('OPENAI_API_KEY')),'version':VERSION,'checks':{'owner_password':bool(os.getenv('JARVIS_OWNER_PASSWORD')),'openai':bool(os.getenv('OPENAI_API_KEY')),'render_key':bool(os.getenv('RENDER_API_KEY')),'operator':operator.status()}}
@app.post('/api/login')
def login(x:Login):
 expected=os.getenv('JARVIS_OWNER_PASSWORD','')
 if not expected or not hmac.compare_digest(x.password,expected):raise HTTPException(401,'Invalid password')
 r=JSONResponse({'ok':True});r.set_cookie(COOKIE,session(),httponly=True,secure=os.getenv('JARVIS_COOKIE_SECURE','1')=='1',samesite='lax',max_age=2592000);return r
@app.post('/api/logout')
def logout():r=JSONResponse({'ok':True});r.delete_cookie(COOKIE);return r
@app.get('/api/dashboard')
def dashboard(req:Request):
 owner(req);return {'ok':True,'version':VERSION,'operator':operator.status(),'objectives':operator.list_objectives(),'activity':operator.list_activity(40),'approval':operator.pending_approval(),'tasks':list_tasks().get('tasks',[]),'render_configured':bool(os.getenv('RENDER_API_KEY')),'integrations':[{'name':'OpenAI','connected':bool(os.getenv('OPENAI_API_KEY')),'role':'Reasoning / planning'},{'name':'Render','connected':bool(os.getenv('RENDER_API_KEY')),'role':'Infrastructure / deployment'},{'name':'Shopify','connected':False,'role':'Store / orders / products'},{'name':'Email','connected':False,'role':'Business communications'},{'name':'Accounting','connected':False,'role':'Books / payments / reporting'},{'name':'Inventory & Suppliers','connected':False,'role':'Stock / purchasing / fulfillment'}]}
@app.post('/api/objectives')
def create_objective(x:Objective,req:Request):owner(req);return {'ok':True,'objective_id':operator.create_objective(x.objective,max(1,min(100,x.priority)))}
@app.get('/api/objectives/{oid}')
def objective(oid:int,req:Request):owner(req);return operator.get_objective(oid)
@app.post('/api/approvals/{aid}')
def approval(aid:int,x:Decision,req:Request):owner(req);return operator.decide_approval(aid,x.approved)
@app.get('/api/render/services')
def services(req:Request):owner(req);return render_services()
PAGE=r'''<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>Panther Peptides Command Center</title><style>:root{--bg:#050b13;--p:#0d1b2d;--line:#294765;--t:#f2f7ff;--m:#93abc3;--g:#35d39a;--r:#ff7185;--a:#f0b64b;--b:#4b9dff}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 50% -15%,#183a61,#07111f 40%,#040910);color:var(--t);font:15px system-ui;min-height:100vh}.w{max-width:1500px;margin:auto;padding:18px}.top,.row,.actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.top{justify-content:space-between}.logo{width:48px;height:48px;border-radius:14px;background:linear-gradient(135deg,#4b9dff,#53dfc0);display:grid;place-items:center;color:#05101d;font-weight:900}h1,h2,h3{margin:0}.muted{color:var(--m)}.card{background:linear-gradient(180deg,#102138,#091626);border:1px solid var(--line);border-radius:18px;padding:18px}.btn{border:1px solid #315779;background:#10243d;color:white;padding:11px 14px;border-radius:11px;font-weight:750;cursor:pointer}.primary{background:#174d8b}.yes{background:#123d32}.no{background:#431b25}.field{width:100%;background:#06111f;border:1px solid #315779;color:white;border-radius:11px;padding:13px}.strategy{display:grid;grid-template-columns:1fr auto;gap:10px;margin:15px 0}.metrics{display:grid;grid-template-columns:repeat(6,1fr);gap:10px;margin:15px 0}.metric b{display:block;font-size:25px}.grid{display:grid;grid-template-columns:1.35fr .85fr;gap:15px}.event{border:1px solid #203b57;border-radius:12px;padding:11px;margin-top:8px;background:#081522}.pill{display:inline-block;border:1px solid #365a7c;border-radius:999px;padding:5px 9px;font-size:12px}.online,.completed,.connected{color:#bdf5df;border-color:#286b59}.blocked,.disconnected{color:#ffabb8;border-color:#8c3448}.running{color:#b9dcff;border-color:#3b6f9d}.queued,.awaiting_approval{color:#ffdc91;border-color:#8a6723}.tabs{display:flex;gap:8px;margin:14px 0;overflow:auto}.tab.active{outline:2px solid #4b9dff}.hidden{display:none}.banner,.notice{margin:14px 0;padding:11px 14px;border-radius:12px}.banner{border:1px solid #285f51;background:#0d2923;color:#c8f5e4}.notice{border:1px solid #8a6723;background:#2a2110;color:#ffdc91}.approval{border:2px solid var(--a);margin:15px 0}.login{max-width:500px;margin:8vh auto}.integration{display:grid;grid-template-columns:1fr auto;gap:10px}.detail{white-space:pre-wrap;font-size:13px;max-height:180px;overflow:auto}@media(max-width:900px){.w{padding:10px}.metrics{grid-template-columns:repeat(2,1fr)}.grid,.strategy{grid-template-columns:1fr}.btn{min-height:44px}}</style></head><body><div class="w"><header class="top"><div class="row"><div class="logo">PP</div><div><h1>Panther Peptides</h1><div class="muted">Jarvis 3 Autonomous Business Command Center · <span id="ver">starting</span></div></div></div><div class="actions"><span id="state" class="pill queued">Starting…</span><button class="btn" onclick="load()">Refresh</button><button id="logout" class="btn hidden" onclick="doLogout()">Logout</button></div></header><div id="notice" class="notice hidden"></div><div id="login" class="card login"><h2>Owner Access</h2><p class="muted">Authenticate to load the business dashboard.</p><input id="pw" class="field" type="password" placeholder="Owner password" onkeydown="if(event.key==='Enter')doLogin()"><p><button class="btn primary" onclick="doLogin()">Open Jarvis</button></p><p id="err"></p></div><main id="app" class="hidden"><div class="banner">OPERATING MODE — Jarvis executes through connected business systems, records evidence, and surfaces owner decisions. Missing systems are shown explicitly under Integrations.</div><section id="approval" class="card approval hidden"></section><div class="strategy"><input id="objective" class="field" placeholder="Give Jarvis a business outcome — not a question" onkeydown="if(event.key==='Enter')runObjective()"><button class="btn primary" onclick="runObjective()">Run Autonomously</button></div><div id="metrics" class="metrics"></div><div class="tabs"><button class="btn tab active" onclick="tab('ops',this)">Operations</button><button class="btn tab" onclick="tab('tasks',this)">Business Tasks</button><button class="btn tab" onclick="tab('systems',this)">Integrations</button><button class="btn tab" onclick="tab('history',this)">Action History</button></div><section id="ops" class="grid"><div class="card"><h2>Active & Recent Objectives</h2><div id="objectives"></div></div><div class="card"><h2>Live Activity</h2><div id="activity"></div></div></section><section id="tasks" class="card hidden"><h2>Persistent Business Tasks</h2><p class="muted">Work Jarvis has created and is tracking across objectives.</p><div id="tasklist"></div></section><section id="systems" class="card hidden"><h2>Business Systems</h2><p class="muted">Jarvis can only perform real external actions through connected systems. This is the capability map.</p><div id="integrations"></div></section><section id="history" class="card hidden"><h2>Verified Action History</h2><p class="muted">Tool calls, approvals, verification and objective state changes.</p><div id="historylist"></div></section></main></div><script>const $=x=>document.getElementById(x);let D=null,A=null;const e=s=>String(s??'').replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));async function req(u,o={}){let r=await fetch(u,{...o,cache:'no-store'}),d=await r.json().catch(()=>({}));if(!r.ok){let x=Error(d.detail||d.error||('HTTP '+r.status));x.status=r.status;throw x}return d}function note(t){$('notice').textContent=t;$('notice').classList.toggle('hidden',!t)}async function doLogin(){try{await req('/api/login',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({password:$('pw').value})});$('pw').value='';await load()}catch(x){$('err').textContent=x.message}}async function doLogout(){await fetch('/api/logout',{method:'POST'});location.reload()}function tab(id,b){['ops','tasks','systems','history'].forEach(x=>$(x).classList.toggle('hidden',x!==id));document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));b.classList.add('active')}function pill(s){return `<span class="pill ${e(s)}">${e(s)}</span>`}async function load(){try{D=await req('/api/dashboard');$('login').classList.add('hidden');$('app').classList.remove('hidden');$('logout').classList.remove('hidden');$('ver').textContent='v'+D.version;let r=D.operator;$('state').textContent=r.worker_alive?'Jarvis online':'Runtime attention';$('state').className='pill '+(r.worker_alive?'online':'blocked');render()}catch(x){if(x.status===401){$('login').classList.remove('hidden');$('app').classList.add('hidden')}else note('Dashboard connection problem: '+x.message)}}function render(){let r=D.operator;$('metrics').innerHTML=[['Running',r.running],['Queued',r.queued],['Approvals',r.awaiting_approval],['Blocked',r.blocked],['Completed',r.completed],['Connected systems',(D.integrations||[]).filter(x=>x.connected).length]].map(x=>`<div class="card metric"><span class="muted">${x[0]}</span><b>${x[1]}</b></div>`).join('');$('objectives').innerHTML=(D.objectives||[]).slice(0,20).map(x=>`<div class="event"><b>#${x.id} ${e(x.title)}</b><div>${pill(x.state)} · step ${x.step}</div>${x.result?`<div class="muted">${e(x.result)}</div>`:''}${x.blocked_reason?`<div class="muted">Blocked: ${e(x.blocked_reason)}</div>`:''}</div>`).join('')||'<p class="muted">No objectives yet.</p>';$('activity').innerHTML=(D.activity||[]).slice(0,10).map(x=>`<div class="event"><b>${e(x.tool||x.kind)} · ${e(x.status)}</b><div class="muted">#${x.objective_id} ${e(x.objective_title||'')}</div></div>`).join('')||'<p class="muted">No activity yet.</p>';$('tasklist').innerHTML=(D.tasks||[]).map(x=>`<div class="event"><b>${e(x.title)}</b> ${pill(x.status)}<div class="muted">${e(x.notes||'')}</div></div>`).join('')||'<p class="muted">No persistent tasks.</p>';$('integrations').innerHTML=(D.integrations||[]).map(x=>`<div class="event integration"><div><b>${e(x.name)}</b><div class="muted">${e(x.role)}</div></div>${pill(x.connected?'connected':'disconnected')}</div>`).join('');$('historylist').innerHTML=(D.activity||[]).map(x=>`<div class="event"><b>${e(x.kind)} · ${e(x.tool||'system')} · ${e(x.status)}</b><div class="muted">Objective #${x.objective_id} · cycle ${x.cycle}</div><div class="detail muted">${e(x.detail||'')}</div></div>`).join('')||'<p class="muted">No recorded actions.</p>';A=D.approval;$('approval').classList.toggle('hidden',!A);if(A)$('approval').innerHTML=`<div class="muted">JARVIS NEEDS ONE DECISION</div><h2>${e(A.objective_title||'Owner approval')}</h2><p>${e(A.question)}</p><div class="actions"><button class="btn yes" onclick="decide(true)">✓ APPROVE</button><button class="btn no" onclick="decide(false)">✕ DENY</button></div>`}async function decide(ok){if(!A)return;await req('/api/approvals/'+A.id,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({approved:ok})});load()}async function runObjective(){let t=$('objective').value.trim();if(!t)return;$('objective').value='';try{let d=await req('/api/objectives',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({objective:t,priority:50})});note('Objective #'+d.objective_id+' queued. Jarvis is working it.');setTimeout(load,700)}catch(x){note('Could not queue objective: '+x.message)}}load();setInterval(()=>{if(!$('app').classList.contains('hidden'))load()},4000)</script></body></html>'''
@app.get('/',response_class=HTMLResponse)
def home():return PAGE
